<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Requests\KycDocumentRequest; use App\Models\KycCase; use App\Services\CountryEligibilityService; use App\Services\PrivateDocumentStorage; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
final class KycController { public function show(Request $request): JsonResponse { $case=KycCase::with('documents')->firstOrCreate(['user_id'=>$request->user()->id],['status'=>'not_started','country_code'=>$request->user()->country_code]); return response()->json(['data'=>$case]); } public function submit(KycDocumentRequest $request,CountryEligibilityService $eligibility,PrivateDocumentStorage $storage): JsonResponse { $user=$request->user(); abort_unless($user->country_code && $eligibility->capability($user->country_code,'kyc_enabled'),403,'KYC is not available in your country.'); $case=KycCase::firstOrCreate(['user_id'=>$user->id],['status'=>'not_started','country_code'=>$user->country_code]); $file=$request->file('document'); $key=$storage->put($file,'kyc/'.$case->id); $document=$case->documents()->create(['document_type'=>$request->string('document_type'),'storage_key'=>$key,'mime_type'=>$file->getMimeType(),'size_bytes'=>$file->getSize(),'scan_status'=>'pending','review_status'=>'pending','uploaded_at'=>now()]); $case->update(['status'=>'under_review','submitted_at'=>now()]); return response()->json(['data'=>['case'=>$case,'document_id'=>$document->id,'status'=>'under_review'],'message'=>'Document received for review. Upload does not mean approval.'],201); } }
